import{MASKS,roleQuarters}from'./smart-model.js';
// Recipes contain tile indices only. Pixels always come from the user's loaded ROM.
export function nativeTerrainPack(reader,native,sourceId,profiles,canvasFactory=()=>document.createElement('canvas')){
 const city=reader.byKey('3.1');if(reader.engine!=='frlg'||!city||native.layout.primary!==city.layout.primary)throw Error('Matching brushes currently support the Kanto outdoor tileset. Use Source tiles or define a custom terrain for this map.');
 const atlas=reader.atlas(native),source=canvasFactory();source.width=atlas.width;source.height=atlas.height;const sc=source.getContext('2d'),im=sc.createImageData(atlas.width,atlas.height);im.data.set(atlas.pixels);sc.putImageData(im,0,0);
 const crop=id=>{const c=canvasFactory();c.width=c.height=16;c.getContext('2d').drawImage(source,id%16*16,Math.floor(id/16)*16,16,16,0,0,16,16);return c;},pixels=c=>c.getContext('2d').getImageData(0,0,16,16),key=(d,i)=>Array.from(d.subarray(i,i+4)).join(',');
 function inside(roles,bg,q){const c=canvasFactory();c.width=c.height=16;const ctx=c.getContext('2d');ctx.drawImage(roles.center,0,0);const h=pixels(roles[q%2?'e':'w']).data,v=pixels(roles[q>>1?'s':'n']).data,center=pixels(roles.center).data,background=pixels(bg).data,cp=new Set(),bp=new Set();for(let p=0;p<center.length;p+=4){if(center[p+3])cp.add(key(center,p));bp.add(key(background,p));}const rank=(d,p)=>!d[p+3]?0:cp.has(key(d,p))&&!bp.has(key(d,p))?2:bp.has(key(d,p))&&!cp.has(key(d,p))?0:cp.has(key(d,p))?2:1,out=pixels(c);for(let y=(q>>1)*8;y<(q>>1)*8+8;y++)for(let x=q%2*8;x<q%2*8+8;x++){const p=(y*16+x)*4;out.data.set((rank(h,p)>=rank(v,p)?h:v).subarray(p,p+4),p);}ctx.putImageData(out,0,0);return c;}
 const assets=[],terrains=[],prefix='rom-terrain-'+sourceId+'-'+reader.pairKey(native)+'-',place=native.label||'Current map';
 function add(token,label,roles,behavior=0){const c=canvasFactory();c.width=128;c.height=96;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;MASKS.forEach((mask,i)=>roleQuarters(mask).forEach((name,q)=>ctx.drawImage(roles[name],q%2*8,(q>>1)*8,8,8,i%8*16+q%2*8,Math.floor(i/8)*16+(q>>1)*8,8,8)));const id=prefix+token;assets.push({id,name:place+' · '+label,width:128,height:96,tileSize:16,category:'ROM-matched terrain',data:c.toDataURL('image/png')});terrains.push({id,assetId:id,name:place+' · '+label,category:'Current ROM · '+place,tags:['rom matched','viridian',label],locations:[place],paintLayer:'ground',movementMode:'walk',movementBehavior:behavior,source:sourceId});}
 for(const f of profiles.families.filter(f=>f.id.startsWith('kanto-'))){const roles=Object.fromEntries(Object.entries(f.roles).map(([k,id])=>[k,crop(id)])),bg=crop(f.background);for(const[name,q]of[['innw',0],['inne',1],['insw',2],['inse',3]])roles[name]??=inside(roles,bg,q);add(f.id,f.name.replace(/^Kanto\s*[—–-]\s*/,''),roles);}
 const allRoles=['nw','n','ne','w','center','e','sw','s','se','innw','inne','insw','inse'];add('grass','Grass ground',Object.fromEntries(allRoles.map(k=>[k,crop(1)])));
 const grass=Array.from(atlas.attrs).findIndex(a=>(a&511)===2);if(grass>=0)add('encounter-grass','Encounter grass',Object.fromEntries(allRoles.map(k=>[k,crop(grass)])),2);
 return{assets,terrains};
}
